109	+package hotel.documents;
110	+
111	+import hotel.reservations.Reservation;
112	+import hotel.rooms.Room;
113	+import java.math.BigDecimal;
114	+import java.time.LocalDate;
115	+import java.util.List;
116	+
117	+/** How one kind of document is written: the sequence of lines is the same, each kind words and formats it. */
118	+abstract class DocumentLayout {
119	+
120	+    abstract String title();
121	+
122	+    abstract String numberSign();
123	+
124	+    /** The line(s) that say who the document is for. */
125	+    abstract List<String> identityLines(Reservation reservation);
126	+
127	+    abstract String roomLabel();
128	+
129	+    abstract String checkInLabel();
130	+
131	+    abstract String checkOutLabel();
132	+
133	+    abstract String nights(int count);
134	+
135	+    abstract String subtotalLabel();
136	+
137	+    abstract String discountLabel();
138	+
139	+    abstract String totalLabel();
140	+
141	+    abstract String money(BigDecimal amount);
142	+
143	+    abstract String date(LocalDate date);
144	+
145	+    /** Lines after the total; none by default. */
146	+    List<String> closingLines(Reservation reservation) {
147	+        return List.of();
148	+    }
149	+
150	+    final String render(Reservation reservation, Room room) {
151	+        StringBuilder text = new StringBuilder();
152	+        line(text, title() + " " + numberSign() + " " + reservation.id());
153	+        identityLines(reservation).forEach(identity -> line(text, identity));
154	+        line(text, roomLabel() + ": " + room.number() + " (" + room.type() + ")");
155	+        line(text, checkInLabel() + ": " + date(reservation.checkIn())
156	+                + " | " + checkOutLabel() + ": " + date(reservation.checkOut())
157	+                + " | " + nights(reservation.price().nights()));
158	+        line(text, subtotalLabel() + ": " + money(reservation.price().subtotal()));
159	+        if (reservation.price().discount().signum() > 0) {
160	+            line(text, discountLabel() + ": " + money(reservation.price().discount()));
161	+        }
162	+        line(text, totalLabel() + ": " + money(reservation.price().total()));
163	+        closingLines(reservation).forEach(closing -> line(text, closing));
164	+        return text.toString();
165	+    }
166	+
167	+    private static void line(StringBuilder text, String line) {
168	+        text.append(line).append('\n');
169	+    }
170	+}
