609	new file mode 100644
610	index 0000000..840f027
611	--- /dev/null
612	+++ b/src/main/java/hotel/web/IdentificationReader.java
613	@@ -0,0 +1,53 @@
614	+package hotel.web;
615	+
616	+import hotel.reservations.ErrorCode;
617	+import hotel.reservations.HotelException;
618	+import hotel.reservations.Identification;
619	+import java.util.List;
620	+import java.util.function.Function;
621	+
622	+/** Reads how the guest is identified from the request: exactly one kind, with all of its fields. */
623	+final class IdentificationReader {
624	+
625	+    /** One way of identifying a guest: the values its fields have in the request, and what they build. */
626	+    private record Kind(List<String> values, Function<List<String>, Identification> build) {
627	+
628	+        boolean isAbsent() {
629	+            return values.stream().allMatch(IdentificationReader::isBlank);
630	+        }
631	+
632	+        boolean isComplete() {
633	+            return values.stream().noneMatch(IdentificationReader::isBlank);
634	+        }
635	+    }
636	+
637	+    private IdentificationReader() {
638	+    }
639	+
640	+    static Identification read(CreateReservationRequest body) {
641	+        List<Kind> kinds = List.of(
642	+                new Kind(List.of(text(body.guestCpf())),
643	+                        values -> new Identification.Cpf(values.get(0))),
644	+                new Kind(List.of(text(body.companyCnpj()), text(body.companyName())),
645	+                        values -> new Identification.Company(values.get(0), values.get(1))),
646	+                new Kind(List.of(text(body.guestPassport()), text(body.guestCountry())),
647	+                        values -> new Identification.Passport(values.get(0), values.get(1))));
648	+
649	+        List<Kind> given = kinds.stream().filter(kind -> !kind.isAbsent()).toList();
650	+        if (given.size() != 1 || !given.get(0).isComplete()) {
651	+            throw new HotelException(
652	+                    ErrorCode.INVALID_REQUEST,
653	+                    "identify the guest with exactly one of: guestCpf, companyCnpj with companyName, "
654	+                            + "or guestPassport with guestCountry");
655	+        }
656	+        return given.get(0).build().apply(given.get(0).values());
657	+    }
658	+
659	+    private static String text(String value) {
660	+        return value == null ? "" : value;
661	+    }
662	+
663	+    private static boolean isBlank(String value) {
664	+        return value.isBlank();
665	+    }
666	+}
