+    private static String reservationWith(String identification) {
+        return """
+                {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
+                 %s "checkIn": "2027-07-10", "checkOut": "2027-07-12", "guests": 2, "ratePlan": "STANDARD"}
+                """.formatted(identification);
+    }
+
+    @Test
+    void identifiesTheGuestByExactlyOneKind() throws Exception {
+        String company = "\"companyCnpj\": \"12.345.678/0001-90\", \"companyName\": \"Tecnosul Ltda\",";
+        String passport = "\"guestPassport\": \"X1234567\", \"guestCountry\": \"United Kingdom\",";
+        for (String invalid : new String[] {
+                "",
+                "\"companyCnpj\": \"12.345.678/0001-90\",",
+                "\"guestPassport\": \"X1234567\",",
+                "\"guestCpf\": \"111.222.333-44\"," + company,
+                company + passport,
+                "\"guestCpf\": \" \","}) {
+            HttpResponse<String> response = post("/reservations", reservationWith(invalid));
+            assertEquals(400, response.statusCode(), invalid);
+            assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
+        }
+
+        JsonNode created = json.readTree(post("/reservations", reservationWith(company)).body());
+        assertEquals("Tecnosul Ltda", created.get("companyName").asText());
+        assertTrue(created.get("guestCpf").isNull());
+        assertTrue(created.get("guestPassport").isNull());
+    }
+
+    @Test
+    void servesTheDocumentOfEachKindOfGuest() throws Exception {
+        String passport = "\"guestPassport\": \"X1234567\", \"guestCountry\": \"United Kingdom\",";
+        long id = json.readTree(post("/reservations", reservationWith(passport)).body()).get("id").asLong();
+        post("/reservations/" + id + "/confirmation", "");
+
+        JsonNode document = json.readTree(get("/reservations/" + id + "/document").body());
+        assertEquals("Booking receipt", document.get("title").asText());
+        assertEquals("United Kingdom", document.get("guestCountry").asText());
+        assertTrue(document.get("guestCpf").isNull());
+        assertTrue(document.get("companyCnpj").isNull());
+        assertTrue(document.get("text").asText().startsWith("Booking receipt no. " + id + "\n"));
+    }
 }

